sp_widget.client_script:
api.controller = function($scope) {
  var c = this;
  c.busy = false;

  c.act = function(row, action) {
    if (c.busy || !row.sysId) {
      return;
    }
    c.busy = true;
    $scope.data.notice = '';

    $scope.server.get({
      action: action,
      sysId:  row.sysId
    }).then(function(response) {
      $scope.data.upcoming  = response.data.upcoming;
      $scope.data.past      = response.data.past;
      $scope.data.count     = response.data.count;
      $scope.data.pastCount = response.data.pastCount;
      $scope.data.notice    = response.data.notice;
      c.busy = false;
    }, function() {
      // Previously this failed silently.
      $scope.data.notice = "Something went wrong. Try again in a moment.";
      c.busy = false;
    });
  };

  $scope.act = c.act;
};

sp_widget.css:
.wrm-res-head { display: flex; align-items: baseline; gap: 12px; margin-bottom: 14px; }
.wrm-res-head h2 { margin: 0; font-size: 22px; color: var(--ink); }
.wrm-res-count { font-size: 13px; color: var(--ink-3); }

.wrm-notice {
  background: var(--held-bg);
  color: var(--held-fg);
  font-size: 13px;
  padding: 10px 14px;
  border-radius: var(--r-soft);
  margin-bottom: 12px;
}

.wrm-res-rows {
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--r-card);
  overflow: hidden;
}
.wrm-res-row {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 15px 16px;
  border-bottom: 1px solid var(--line);
}
.wrm-res-row:last-child { border-bottom: 0; }

.wrm-when { width: 192px; flex: none; }

.wrm-when-labels {
  display: flex;
  font-size: 10px;
  letter-spacing: .07em;
  color: var(--ink-3);
  margin-bottom: 5px;
}
.wrm-when-labels.two { justify-content: space-between; }

.wrm-when-rail { display: flex; align-items: center; gap: 7px; }
.wrm-when-rail .tm { font-size: 13px; color: var(--ink); }
.wrm-when-rail .dot { width: 6px; height: 6px; border-radius: 50%; flex: none; }
.wrm-when-rail .dot.start { background: var(--clay); }
.wrm-when-rail .dot.end { border: 1px solid var(--clay); }
.wrm-when-rail .dot.end.done { background: var(--clay); }
.wrm-when-rail .track {
  flex: 1;
  height: 2px;
  background: var(--line);
  border-radius: 2px;
  overflow: hidden;
}
.wrm-when-rail .fill {
  display: block;
  height: 100%;
  background: var(--clay);
}

.wrm-when-dur { text-align: center; font-size: 10px; color: var(--ink-3); margin-top: 4px; }
.wrm-when-dur .live { color: var(--clay); }

.wrm-res-main { flex: 1; min-width: 0; }
.wrm-res-main .t { font-size: 14px; color: var(--ink); }
.wrm-res-main .s { font-size: 11px; color: var(--ink-3); }
.wrm-res-main .n { font-size: 10px; color: var(--ink-3); letter-spacing: .06em; margin-top: 2px; }

.wrm-res-pill {
  font-size: 11px;
  padding: 5px 12px;
  border-radius: var(--r-pill);
  white-space: nowrap;
  flex: none;
}
.wrm-res-pill.free  { background: var(--free-bg); color: var(--free-fg); }
.wrm-res-pill.held  { background: var(--held-bg); color: var(--held-fg); }
.wrm-res-pill.out   { background: var(--out-bg);  color: var(--out-fg); }
.wrm-res-pill.quiet { background: var(--surface-2); color: var(--ink-3); }

.wrm-res-actions { flex: none; display: flex; gap: 8px; }
.wrm-res-btn {
  font-size: 12px;
  font-weight: 500;
  padding: 8px 18px;
  border: 0;
  border-radius: var(--r-pill);
  background: var(--clay);
  color: var(--on-clay);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22);
  white-space: nowrap;
  cursor: pointer;
}
.wrm-res-btn:hover { background: var(--clay-press); }
.wrm-res-btn:focus-visible { outline: 2px solid var(--clay); outline-offset: 3px; }
.wrm-res-btn.ghost {
  background: transparent;
  color: var(--ink-2);
  box-shadow: inset 0 0 0 1px var(--line);
}
.wrm-res-btn.ghost:hover { background: var(--surface-2); color: var(--ink); }

.wrm-past { margin-top: 20px; }
.wrm-past-head {
  font-size: 11px;
  letter-spacing: .08em;
  color: var(--ink-3);
  margin-bottom: 8px;
}
.wrm-res-rows.past { opacity: .62; }

.wrm-res-empty {
  text-align: center;
  padding: 38px 20px;
  background: var(--surface);
  border: 1px dashed var(--line);
  border-radius: var(--r-card);
  color: var(--ink-2);
}
.wrm-res-empty h3 { margin: 0 0 6px; font-size: 17px; color: var(--ink); }
.wrm-res-empty p  { margin: 0; font-size: 13px; }

.wrm-rebook { margin-top: 28px; }

.wrm-rebook-cards {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 10px;
}

.wrm-rebook-card {
  flex: 1 1 220px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 12px 12px 12px 3px;
  padding: 14px 16px;
}

.wrm-rebook-card .t { font-weight: 600; color: var(--ink); }
.wrm-rebook-card .s { font-size: 12px; color: var(--ink-3); }
.wrm-rebook-card .n { font-size: 11px; color: var(--ink-3); margin-top: 2px; }

.wrm-rebook-card .wrm-res-btn { text-decoration: none; white-space: nowrap; }

.wrm-collapse-toggle { cursor: pointer; user-select: none; }
.wrm-collapse-toggle .fa { font-size: 10px; margin-left: 6px; }

sp_widget.script:
(function() {

  var MONTHS   = ['JAN','FEB','MAR','APR','MAY','JUN',
                  'JUL','AUG','SEP','OCT','NOV','DEC'];
  var WEEKDAYS = ['SUN','MON','TUE','WED','THU','FRI','SAT'];

  var TINTS = {
    pending_check_in: 'held',
    checked_in:       'free',
    checked_out:      'quiet',
    cancelled:        'quiet',
    no_show:          'out'
  };

  // Statuses that mean the reservation is finished regardless of date.
  var CLOSED = ['checked_out', 'cancelled', 'no_show'];

  // How early someone may check in, in minutes before the start time.
  var CHECKIN_LEAD_MIN = 60;

  var nowMs = new GlideDateTime().getNumericValue();

  // Split "YYYY-MM-DD HH:mm:ss" into display parts.
  // Date.UTC keeps the weekday stable regardless of server timezone.
  function parts(dt) {
    if (!dt) return { month:'', day:'', time:'', weekday:'', ymd:'' };
    var p = dt.split(' ');
    var d = p[0].split('-');
    var y = parseInt(d[0], 10);
    var m = parseInt(d[1], 10);
    var dd = parseInt(d[2], 10);
    var js = new Date(Date.UTC(y, m - 1, dd));
    return {
      month:   MONTHS[m - 1],
      day:     d[2],
      time:    p[1] ? p[1].substring(0, 5) : '',
      weekday: WEEKDAYS[js.getUTCDay()],
      ymd:     p[0]
    };
  }

  // Calendar days spanned, inclusive. 28th to 29th is 2 days.
  function spanLabel(a, b) {
    if (!a || !b) return '';
    var A = a.split('-'), B = b.split('-');
    var t1 = Date.UTC(+A[0], +A[1] - 1, +A[2]);
    var t2 = Date.UTC(+B[0], +B[1] - 1, +B[2]);
    var n = Math.round((t2 - t1) / 86400000) + 1;
    if (n < 1) n = 1;
    return n + (n === 1 ? ' day' : ' days');
  }

  // How far through the booking we are, 0-100.
  // Uses raw UTC values so it doesn't depend on display timezone.
  function progressPct(startRaw, endRaw) {
    if (!startRaw || !endRaw) return 0;
    var s = new GlideDateTime(startRaw).getNumericValue();
    var e = new GlideDateTime(endRaw).getNumericValue();
    if (e <= s) return nowMs >= e ? 100 : 0;
    if (nowMs <= s) return 0;
    if (nowMs >= e) return 100;
    return Math.round(((nowMs - s) / (e - s)) * 100);
  }

  // "09:00 on Tue 28 Jul" — built from the display value so it
  // reads in the user's own timezone.
  function whenPhrase(displayDt) {
    var p = parts(displayDt);
    if (!p.time) return 'the start time';
    var wd = p.weekday.charAt(0) + p.weekday.substring(1).toLowerCase();
    var mo = p.month.charAt(0) + p.month.substring(1).toLowerCase();
    return p.time + ' on ' + wd + ' ' + p.day + ' ' + mo;
  }

  // --- handle check-in / check-out posted from the client ---
  data.notice = '';

  if (input && input.action) {
    var res = new GlideRecord('x_1903615_worksp_0_reservation_tracker');

    if (!res.get(input.sysId)) {
      data.notice = "That reservation couldn't be found.";

    } else if (res.getValue('reserved_for') !== gs.getUserID()) {
      // Only act on a record this user actually owns.
      data.notice = "That reservation isn't yours to change.";

    } else if (input.action === 'checkin') {
      var cStart = res.getValue('work_start');
      var cEnd   = res.getValue('work_end');
      var startMs = cStart ? new GlideDateTime(cStart).getNumericValue() : 0;
      var endMs   = cEnd   ? new GlideDateTime(cEnd).getNumericValue()   : 0;
      var opensMs = startMs - (CHECKIN_LEAD_MIN * 60 * 1000);

      if (res.getValue('reservation_status') !== 'pending_check_in') {
        data.notice = 'This reservation is no longer waiting for check-in.';

      } else if (startMs && nowMs < opensMs) {
        // The guard: too early. Tell them exactly when it opens.
        data.notice = 'You can check in from ' +
                      whenPhrase(res.getDisplayValue('work_start')) + '.';

      } else if (endMs && nowMs > endMs) {
        data.notice = 'This reservation has already ended.';

      } else {
        res.setValue('reservation_status', 'checked_in');
        res.work_notes = 'Reservation checked in by ' + gs.getUserDisplayName();
        res.update();
      }

    } else if (input.action === 'checkout') {
      if (res.getValue('reservation_status') !== 'checked_in') {
        data.notice = 'You need to check in before checking out.';
      } else {
        res.setValue('reservation_status', 'checked_out');
        res.setValue('state', 3);   // Closed Complete
        res.work_notes = 'Reservation checked out by ' + gs.getUserDisplayName();
        res.update();
      }
    }
  }

  var rows = [];

  // Rebook map: one entry per distinct workspace the user has
  // actually used before, so we can offer "book again" shortcuts.
  var rebookMap = {};

  // --- 1. Real reservation records ---
  var linked = [];                     // RITMs that already produced a tracker

  var gr = new GlideRecord('x_1903615_worksp_0_reservation_tracker');
  gr.addQuery('reserved_for', gs.getUserID());
  gr.orderBy('work_start');
  gr.query();

  while (gr.next()) {
    var startRaw = gr.getValue('work_start');
    var endRaw   = gr.getValue('work_end');
    var s = parts(gr.getDisplayValue('work_start'));
    var e = parts(gr.getDisplayValue('work_end'));
    var status = gr.getValue('reservation_status');

    var req = gr.getValue('request_number');
    if (req) linked.push(req);

    var rEndMs = endRaw ? new GlideDateTime(endRaw).getNumericValue() : 0;
    var closed = CLOSED.indexOf(status) > -1;
    var pct    = progressPct(startRaw, endRaw);

    // Count every finished stay toward its workspace's rebook card.
    // Cancelled and no-show don't count - the user never used the space.
    var wsId = gr.getValue('workspace');
    if (wsId && (status === 'checked_out' ||
        (rEndMs > 0 && rEndMs < nowMs && status !== 'cancelled' && status !== 'no_show'))) {
      if (!rebookMap[wsId]) {
        rebookMap[wsId] = {
          wsId:      wsId,
          workspace: gr.getDisplayValue('workspace'),
          location:  gr.getDisplayValue('location'),
          count:     0,
          lastMs:    0
        };
      }
      rebookMap[wsId].count++;
      if (rEndMs > rebookMap[wsId].lastMs) rebookMap[wsId].lastMs = rEndMs;
    }

    rows.push({
      sysId:        gr.getUniqueValue(),
      number:       gr.getValue('number'),
      workspace:    gr.getDisplayValue('workspace'),
      location:     gr.getDisplayValue('location'),
      statusLabel:  gr.getDisplayValue('reservation_status'),
      tint:         TINTS[status] || 'quiet',
      startWeekday: s.weekday,
      startDay:     s.day,
      startMonth:   s.month,
      startTime:    s.time,
      endWeekday:   e.weekday,
      endDay:       e.day,
      endMonth:     e.month,
      endTime:      e.time,
      multiDay:     s.ymd !== e.ymd,
      duration:     spanLabel(s.ymd, e.ymd),
      progress:     closed ? 100 : pct,
      live:         !closed && pct > 0 && pct < 100,
      done:         closed || pct >= 100,
      pending:      false,
      canCheckIn:   status === 'pending_check_in',
      canCheckOut:  status === 'checked_in',
      isPast:       closed || (rEndMs > 0 && rEndMs < nowMs),
      sortMs:       startRaw ? new GlideDateTime(startRaw).getNumericValue() : 0
    });
  }

  // --- 2. Requests still awaiting approval ---
  var ritm = new GlideRecord('sc_req_item');
  ritm.addQuery('request.requested_for', gs.getUserID());
  ritm.addQuery('cat_item', 'fe1e919e93c6c3108c8874dcebba10d0');
  ritm.addQuery('active', true);
  if (linked.length) {
    ritm.addQuery('sys_id', 'NOT IN', linked.join(','));
  }
  ritm.query();

  while (ritm.next()) {
    var vStart = '', vEnd = '', vSpace = '', vLoc = '';
    try {
      vStart = ritm.variables.start_date_time.getDisplayValue();
      vEnd   = ritm.variables.end_date_time.getDisplayValue();
      vSpace = ritm.variables.select_workspace.getDisplayValue();
      vLoc   = ritm.variables.location.getDisplayValue();
    } catch (err) {
      gs.warn('WRM pending row: variable read failed - ' + err);
    }

    var ps = parts(vStart);
    var pe = parts(vEnd);
    var pEndMs = vEnd ? new GlideDateTime(vEnd).getNumericValue() : 0;

    rows.push({
      sysId:        '',
      number:       ritm.getValue('number'),
      workspace:    vSpace || 'Workspace reservation',
      location:     vLoc,
      statusLabel:  'Pending approval',
      tint:         'quiet',
      startWeekday: ps.weekday,
      startDay:     ps.day,
      startMonth:   ps.month,
      startTime:    ps.time,
      endWeekday:   pe.weekday,
      endDay:       pe.day,
      endMonth:     pe.month,
      endTime:      pe.time,
      multiDay:     ps.ymd !== pe.ymd,
      duration:     spanLabel(ps.ymd, pe.ymd),
      progress:     0,
      live:         false,
      done:         false,
      pending:      true,
      canCheckIn:   false,
      canCheckOut:  false,
      isPast:       pEndMs > 0 && pEndMs < nowMs,
      sortMs:       vStart ? new GlideDateTime(vStart).getNumericValue() : 0
    });
  }

  // --- 3. Split and sort ---
  data.upcoming = [];
  var pastAll   = [];

  for (var i = 0; i < rows.length; i++) {
    if (rows[i].isPast) {
      pastAll.push(rows[i]);
    } else {
      data.upcoming.push(rows[i]);
    }
  }

  // Soonest first for upcoming, most recent first for history.
  data.upcoming.sort(function(a, b) { return a.sortMs - b.sortMs; });
  pastAll.sort(function(a, b) { return b.sortMs - a.sortMs; });

  // Cap what we ship to the client: recent history only.
  // pastCount keeps the true total so the heading can say "Recent 5 of 23".
  var PAST_LIMIT = 5;
  data.past       = pastAll.slice(0, PAST_LIMIT);
  data.pastCount  = pastAll.length;
  data.pastCapped = pastAll.length > PAST_LIMIT;

  // --- 4. Rebook cards: distinct past workspaces, most recent first ---
  var rebook = [];
  for (var k in rebookMap) {
    if (rebookMap.hasOwnProperty(k)) rebook.push(rebookMap[k]);
  }
  rebook.sort(function(a, b) { return b.lastMs - a.lastMs; });
  rebook = rebook.slice(0, 4);

  // Build the prefill link server-side so the template stays dumb.
  var CATALOG_URL = '?id=sc_cat_item&sys_id=fe1e919e93c6c3108c8874dcebba10d0';
  for (var r = 0; r < rebook.length; r++) {
    rebook[r].timesLabel = 'Booked ' + rebook[r].count +
                           (rebook[r].count === 1 ? ' time' : ' times');
    rebook[r].bookUrl = CATALOG_URL +
      '&wrm_ws=' + encodeURIComponent(rebook[r].wsId) +
      '&wrm_ws_label=' + encodeURIComponent(rebook[r].workspace);
  }
  data.rebook = rebook;

  // Split the heading count: approved bookings and requests still
  // waiting for approval mean different things to the user.
  var confirmedCount = 0;
  var pendingCount   = 0;
  for (var j = 0; j < data.upcoming.length; j++) {
    if (data.upcoming[j].pending) {
      pendingCount++;
    } else {
      confirmedCount++;
    }
  }

  data.count          = data.upcoming.length;
  data.confirmedCount = confirmedCount;
  data.pendingCount   = pendingCount;
})();
